'use strict';
async function refreshMetrics(){const status=document.getElementById('metrics-status'),button=document.getElementById('refresh-metrics');button.disabled=true;status.textContent='Cargando estadísticas…';try{const response=await fetch('/api/site-metrics',{cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.error||'No disponible');const totals={view:0,amazon:0,whatsapp:0};for(const row of data.rows)totals[row.event]+=row.count;const summary=document.getElementById('metrics-summary');summary.replaceChildren();for(const [title,value]of [['Vistas registradas',totals.view],['Clics hacia Amazon',totals.amazon],['Clics a WhatsApp',totals.whatsapp],['Tasa de clics a Amazon',totals.view?(100*totals.amazon/totals.view).toFixed(1)+' %':'Sin datos']]){const p=document.createElement('p');p.textContent=title+': '+value;summary.append(p);}status.textContent=data.rows.length?'Datos actualizados.':'Todavía no hay eventos con consentimiento.';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}}
document.getElementById('refresh-metrics').addEventListener('click',refreshMetrics);refreshMetrics();
